-- say_phrase («Сказать фразу»), правила v2 по итогам теста на iPhone: модуль больше сам ничего не пишет в чат и не показывает фразу
-- в панели (пузыря с фразой и поля showPhrase нет), задание формулирует предыдущее сообщение автора; кнопок «Ещё раз»/«Получилось»
-- нет; «пара сообщений вокруг say_phrase» (задание перед, успех после) пропускается целиком, когда ученик нажал «Я не могу говорить»;
-- поле strict («Строго») включает консенсус interim+final. Предыдущая миграция (20261009110000) уже могла быть применена, поэтому
-- текст правила ОБНОВЛЯЕМ, а не правим старый файл. Таблиц, колонок, политик и функций не меняем. Идемпотентно: повторный запуск
-- пишет тот же текст; если правила ещё нет (v1 не применяли) — вставляем. Текст тот же, что в lessonRulesDefaults.js (следит тест).
update public.lesson_rules
set rule_text = 'say_phrase («Сказать фразу») — ученик ПРОИЗНОСИТ английскую фразу в микрофон, приложение мягко сверяет её с эталоном (порядок слов не важен, мелкие неточности прощаются, звук не записывается и не сохраняется). phrase — эталон: обычная разговорная фраза на 3–8 слов с целевым словом урока, без перевода внутри; он нужен для проверки и озвучки, а САМ МОДУЛЬ НИЧЕГО В ЧАТ НЕ ПИШЕТ и фразу в панели не показывает (в панели только «Произнесите фразу»), поэтому задание формулирует ПРЕДЫДУЩЕЕ сообщение — короткая текстовая нода прямо перед say_phrase: напиши в ней саму фразу и что сказать вслух. translation — справочно (ученику не показывается); keywords — 1–2 ключевых слова из phrase через запятую (они должны прозвучать обязательно); threshold — 70 по умолчанию (50–100); strict: true — «Строго» (100% слов, точно, без опечаток и без слов, которые распознаватель «домыслил»; у новых нод в редакторе включено, в JSON отсутствие поля = false). Схема «пара сообщений вокруг say_phrase»: [текстовая нода-задание] → [say_phrase] → [текстовая нода-успех: коротко сообщает, что получилось]. Кнопок «Ещё раз» и «Получилось» нет: после неудачи ученик снова жмёт на микрофон, а если не может говорить — «Я не могу говорить»; тогда сообщение-успех не показывается, а следующие такие модули плеер пропускает целиком — вместе с заданием перед ними и успехом после них. Чтобы пара пропускалась, задание — обычная текстовая нода с единственным выходом в say_phrase и единственным входом, успех — обычная текстовая нода с единственным входом от say_phrase; иначе пропускается только сам модуль. Не ставь say_phrase первой нодой урока и две подряд. Триггеры: say_done (основной) и необязательный say_skip («Я не могу говорить»; если соединён, у него приоритет и сообщения-успеха после него нет; если не соединён — идёт say_done).'
where rule_text like 'say_phrase («Сказать фразу») — ученик ПРОИЗНОСИТ%';

insert into public.lesson_rules (rule_text, sort_order, category)
select
  'say_phrase («Сказать фразу») — ученик ПРОИЗНОСИТ английскую фразу в микрофон, приложение мягко сверяет её с эталоном (порядок слов не важен, мелкие неточности прощаются, звук не записывается и не сохраняется). phrase — эталон: обычная разговорная фраза на 3–8 слов с целевым словом урока, без перевода внутри; он нужен для проверки и озвучки, а САМ МОДУЛЬ НИЧЕГО В ЧАТ НЕ ПИШЕТ и фразу в панели не показывает (в панели только «Произнесите фразу»), поэтому задание формулирует ПРЕДЫДУЩЕЕ сообщение — короткая текстовая нода прямо перед say_phrase: напиши в ней саму фразу и что сказать вслух. translation — справочно (ученику не показывается); keywords — 1–2 ключевых слова из phrase через запятую (они должны прозвучать обязательно); threshold — 70 по умолчанию (50–100); strict: true — «Строго» (100% слов, точно, без опечаток и без слов, которые распознаватель «домыслил»; у новых нод в редакторе включено, в JSON отсутствие поля = false). Схема «пара сообщений вокруг say_phrase»: [текстовая нода-задание] → [say_phrase] → [текстовая нода-успех: коротко сообщает, что получилось]. Кнопок «Ещё раз» и «Получилось» нет: после неудачи ученик снова жмёт на микрофон, а если не может говорить — «Я не могу говорить»; тогда сообщение-успех не показывается, а следующие такие модули плеер пропускает целиком — вместе с заданием перед ними и успехом после них. Чтобы пара пропускалась, задание — обычная текстовая нода с единственным выходом в say_phrase и единственным входом, успех — обычная текстовая нода с единственным входом от say_phrase; иначе пропускается только сам модуль. Не ставь say_phrase первой нодой урока и две подряд. Триггеры: say_done (основной) и необязательный say_skip («Я не могу говорить»; если соединён, у него приоритет и сообщения-успеха после него нет; если не соединён — идёт say_done).',
  250,
  'principle'
where not exists (
  select 1 from public.lesson_rules
  where rule_text like 'say_phrase («Сказать фразу») — ученик ПРОИЗНОСИТ%'
);
